type CalendarViewMode = "rolling" | "month30";

function startOfDay(d: Date): Date {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function addDays(d: Date, n: number): Date {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function startOfWeekMonday(d: Date): Date {
  const x = startOfDay(d);
  const day = x.getDay();
  const offset = day === 0 ? -6 : 1 - day;
  x.setDate(x.getDate() + offset);
  return x;
}

/** Lokal kalenderdag som YYYY-MM-DD */
function dayKeyLocal(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function parseDayKeyLocal(dayKey: string): Date | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dayKey);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!year || month < 1 || month > 12 || day < 1 || day > 31) return null;
  return new Date(year, month - 1, day);
}

function expandAround(center: Date, beforeAfter: number): Date[] {
  const c = startOfDay(new Date(center));
  const out: Date[] = [];
  for (let i = -beforeAfter; i <= beforeAfter; i++) {
    out.push(addDays(c, i));
  }
  return out;
}

function expandForward(start: Date, count: number): Date[] {
  const s = startOfDay(new Date(start));
  const out: Date[] = [];
  for (let i = 0; i < count; i++) {
    out.push(addDays(s, i));
  }
  return out;
}

function formatDayHeader(d: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    weekday: "short",
    day: "numeric",
    month: "short",
  }).format(d);
}

function rollingDayHeaderThClass(ambient: DayGridAmbient): string {
  const base =
    "border-b px-3 py-2 text-center text-xs font-semibold whitespace-nowrap ";
  if (ambient === "holiday") {
    return `${base} border-zinc-200 bg-amber-50/95 text-zinc-800 dark:border-zinc-700 dark:bg-amber-950/40 dark:text-zinc-100`;
  }
  if (ambient === "weekend") {
    return `${base} border-zinc-200 bg-zinc-200/30 text-zinc-700 dark:border-zinc-700 dark:bg-zinc-800/90 dark:text-zinc-200`;
  }
  return `${base} border-zinc-200 bg-zinc-100 text-zinc-700 dark:border-zinc-700 dark:bg-zinc-800/95 dark:text-zinc-200`;
}

function rollingHourHeaderThClass(ambient: DayGridAmbient): string {
  const base =
    "border-b px-0 py-2 text-center text-[10px] font-medium whitespace-nowrap tabular-nums ";
  if (ambient === "holiday") {
    return `${base} border-zinc-200 bg-amber-50/95 text-zinc-600 dark:border-zinc-700 dark:bg-amber-950/40 dark:text-zinc-300`;
  }
  if (ambient === "weekend") {
    return `${base} border-zinc-200 bg-zinc-200/30 text-zinc-500 dark:border-zinc-700 dark:bg-zinc-800/90 dark:text-zinc-400`;
  }
  return `${base} border-zinc-200 bg-zinc-100 text-zinc-500 dark:border-zinc-700 dark:bg-zinc-800/95 dark:text-zinc-400`;
}

function formatTimeNow(locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).format(new Date());
}

function formatShiftRange(startsAtIso: string, endsAtIso: string, locale: string): string {
  const s = new Date(startsAtIso);
  const e = new Date(endsAtIso);
  const fmt = (d: Date) =>
    new Intl.DateTimeFormat(locale, {
      day: "2-digit",
      month: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    }).format(d);
  return `${fmt(s)} - ${fmt(e)}`;
}

function formatClockDate(iso: string, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso));
}

function toDateTimeLocalValue(iso: string): string {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(
    d.getHours()
  )}:${pad(d.getMinutes())}`;
}

function localInputToIso(value: string, fallbackIso: string): string {
  if (!value) return fallbackIso;
  const ms = new Date(value).getTime();
  if (!Number.isFinite(ms)) return fallbackIso;
  return new Date(ms).toISOString();
}

function touchDistance(
  a: { clientX: number; clientY: number },
  b: { clientX: number; clientY: number }
): number {
  const dx = a.clientX - b.clientX;
  const dy = a.clientY - b.clientY;
  return Math.hypot(dx, dy);
}

function localDateAt(day: Date, hour: number, minute = 0): Date {
  const d = new Date(day);
  d.setHours(hour, minute, 0, 0);
  return d;
}

function truncateTowardZero(value: number): number {
  return value < 0 ? Math.ceil(value) : Math.floor(value);
}

function shiftSlotKey(rowKey: string, day: Date, hour: number): string {
  return `${rowKey}|${dayKeyLocal(day)}|${hour}`;
}

function shiftIdentityKey(shift: WorkplaceShiftRow): string {
  return `${shift.user_id ?? "open"}|${shift.department_id ?? "none"}|${shift.required_employee_type_id ?? "any"}|${shift.starts_at}|${shift.ends_at}|${shift.shift_type_id ?? ""}`;
}

type ShiftViolation = {
  rule_id: string;
  date: string;
  severity: Severity;
  message: string;
};

function severityPriority(severity: Severity): number {
  return severity === "ERROR" ? 2 : 1;
}

function shiftOverlapsViolationDay(shift: WorkplaceShiftRow, violationDate: string): boolean {
  const shiftStart = new Date(shift.starts_at);
  const shiftEnd = new Date(shift.ends_at);
  if (Number.isNaN(shiftStart.getTime()) || Number.isNaN(shiftEnd.getTime())) return false;
  const day = parseDayKeyLocal(violationDate);
  if (!day) return false;
  const dayStartMs = startOfDay(day).getTime();
  const dayEndMs = addDays(startOfDay(day), 1).getTime();
  const shiftStartMs = shiftStart.getTime();
  const shiftEndMs = shiftEnd.getTime();
  return shiftStartMs < dayEndMs && shiftEndMs > dayStartMs;
}

function pushUniqueShiftViolation(target: ShiftViolation[], violation: ShiftViolation): void {
  const key = `${violation.rule_id}|${violation.date}|${violation.severity}|${violation.message}`;
  if (
    target.some(
      (item) => `${item.rule_id}|${item.date}|${item.severity}|${item.message}` === key
    )
  ) {
    return;
  }
  target.push(violation);
}

function buildComplianceViolationMap(
  shifts: WorkplaceShiftRow[],
  violations: EuViolation[]
): Map<string, ShiftViolation[]> {
  const violationByEmployeeDay = new Map<string, EuViolation[]>();
  for (const violation of violations) {
    const key = `${violation.employee_id}|${violation.date}`;
    const list = violationByEmployeeDay.get(key) ?? [];
    list.push(violation);
    violationByEmployeeDay.set(key, list);
  }
  const out = new Map<string, ShiftViolation[]>();
  for (const shift of shifts) {
    if (!shift.user_id) continue;
    const violationsForShift: ShiftViolation[] = [];
    for (const [key, items] of violationByEmployeeDay.entries()) {
      const [employeeId, dayKey] = key.split("|");
      if (employeeId !== shift.user_id) continue;
      if (!shiftOverlapsViolationDay(shift, dayKey)) continue;
      for (const item of items) {
        pushUniqueShiftViolation(violationsForShift, {
          rule_id: item.rule_id,
          date: item.date,
          severity: item.severity,
          message: item.message,
        });
      }
    }
    if (violationsForShift.length === 0) continue;
    violationsForShift.sort((a, b) => {
      const severityDiff = severityPriority(b.severity) - severityPriority(a.severity);
      if (severityDiff !== 0) return severityDiff;
      return a.date.localeCompare(b.date);
    });
    if (shift.id) out.set(shift.id, violationsForShift);
    out.set(shiftIdentityKey(shift), violationsForShift);
  }
  return out;
}

function topShiftViolation(violations: ShiftViolation[] | undefined): ShiftViolation | null {
  if (!violations || violations.length === 0) return null;
  return violations[0] ?? null;
}

const DEFAULT_SHIFT_COLOR = "#94a3b8";

function normalizeCalendarHex(color: string | null | undefined): string {
  const c = color?.trim();
  if (!c) return DEFAULT_SHIFT_COLOR;
  if (/^#[0-9a-fA-F]{6}$/.test(c)) return c;
  return DEFAULT_SHIFT_COLOR;
}

function normalizeEmployeeTypeKey(value: string): string {
  return value
    .trim()
    .toLocaleLowerCase("da")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ");
}

function firstDepartmentLabel(
  m: WorkplaceMemberDepartmentsRow,
  deptById: Map<string, WorkplaceDepartmentRow>
): string {
  const names = m.department_ids
    .map((id) => deptById.get(id)?.name ?? "")
    .filter(Boolean)
    .sort((a, b) => a.localeCompare(b, "da"));
  return names[0] ?? "";
}

function distinctEmployeesOnShiftForDay(
  shifts: WorkplaceShiftRow[],
  day: Date
): number {
  const ds = startOfDay(day).getTime();
  const de = addDays(startOfDay(day), 1).getTime();
  const set = new Set<string>();
  for (const s of shifts) {
    if (!s.user_id) continue;
    const a = new Date(s.starts_at).getTime();
    const b = new Date(s.ends_at).getTime();
    if (a < de && b > ds) set.add(s.user_id);
  }
  return set.size;
}

