const ShiftGridCell = memo(function ShiftGridCell({
  cellKey,
  day,
  dayKey,
  dayAmbient,
  hour,
  userId,
  groupDeptId,
  requiredEmployeeTypeId,
  shift,
  startsHere,
  endsHere,
  has,
  shiftLabel,
  renderedCellStyle,
  hoverDetails,
  violationRule,
  violationSeverity,
  onCellPointerDown,
  onCellPointerUp,
  onCellClick,
  onStartShiftDrag,
}: ShiftGridCellProps) {
  const emptySurface =
    dayAmbient === "holiday"
      ? "bg-amber-50/80 dark:bg-amber-950/30"
      : dayAmbient === "weekend"
        ? "bg-zinc-200/25 dark:bg-zinc-800/50"
        : "bg-zinc-50/50 dark:bg-zinc-950/50";
  const titleWithViolation =
    has && violationRule
      ? hoverDetails?.includes("EU-regel")
        ? hoverDetails
        : [hoverDetails, `EU-regel: ${violationRule}`].filter(Boolean).join("\n")
      : hoverDetails;
  const showCenteredViolationIcon = (() => {
    if (!has || !violationRule || !shift) return false;
    const slotStart = new Date(day);
    slotStart.setHours(hour, 0, 0, 0);
    const slotStartMs = slotStart.getTime();
    const slotEnd = slotStartMs + 60 * 60 * 1000;
    const shiftStart = new Date(shift.starts_at).getTime();
    const shiftEnd = new Date(shift.ends_at).getTime();
    if (!Number.isFinite(shiftStart) || !Number.isFinite(shiftEnd) || shiftEnd <= shiftStart) {
      return false;
    }
    const midpoint = shiftStart + (shiftEnd - shiftStart) / 2;
    return midpoint >= slotStartMs && midpoint < slotEnd;
  })();
  const violationHoverText = violationRule ? `EU-regel: ${violationRule}` : undefined;
  const violationAccentClass =
    violationSeverity === "ERROR"
      ? "ring-1 ring-red-500/80 dark:ring-red-400/80"
      : violationSeverity === "WARNING"
        ? "ring-1 ring-amber-500/80 dark:ring-amber-300/80"
        : "";
  const violationIconClass =
    violationSeverity === "WARNING"
      ? "text-amber-500 [text-shadow:0_0_3px_rgba(255,255,255,1),0_0_8px_rgba(255,255,255,0.95),0_0_14px_rgba(255,184,0,1),0_0_22px_rgba(255,184,0,0.95)]"
      : "text-red-500 [text-shadow:0_0_3px_rgba(255,255,255,1),0_0_8px_rgba(255,255,255,0.95),0_0_14px_rgba(255,80,80,1),0_0_22px_rgba(255,80,80,0.95)]";
  return (
    <td
      key={cellKey}
      className={
        has
          ? `relative border-b border-l border-zinc-300/60 px-0 py-2 dark:border-zinc-600/50 ${violationAccentClass}`
          : `border-b border-l border-zinc-100 px-0 py-2 dark:border-zinc-800 ${emptySurface}`
      }
      style={renderedCellStyle}
      title={titleWithViolation}
      onPointerDown={(e) => onCellPointerDown(e, shift)}
      onPointerUp={onCellPointerUp}
      onPointerCancel={onCellPointerUp}
      onPointerLeave={onCellPointerUp}
      onClick={() =>
        onCellClick(shift, userId, groupDeptId, requiredEmployeeTypeId, day, hour)
      }
      data-shift-id={shift?.id ?? ""}
      data-user-id={userId ?? ""}
      data-day-key={dayKey}
      data-hour={hour}
    >
      {showCenteredViolationIcon ? (
        <span
          className={`absolute left-1/2 top-1/2 z-0 inline-flex h-10 w-10 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-white/80 text-[30px] leading-none dark:bg-white/80 ${violationIconClass}`}
          title={violationHoverText}
          aria-label={violationHoverText}
        >
          ⚠
        </span>
      ) : null}
      {has && startsHere && shiftLabel.trim().length > 0 ? (
        <span className="pointer-events-none block w-full truncate pl-2 pr-0.5 text-left text-[12px] font-bold text-black [text-shadow:0_0_2px_rgba(255,255,255,0.95),0_0_6px_rgba(255,255,255,0.9)]">
          {shiftLabel}
        </span>
      ) : null}
      {has && endsHere ? (
        <button
          type="button"
          className="absolute inset-0 cursor-grab bg-transparent active:cursor-grabbing"
          onPointerDown={(e) => {
            if (!shift) return;
            onStartShiftDrag(e, shift, "move");
          }}
          title="Træk i mønster-området for at flytte vagt"
        />
      ) : null}
      {has && startsHere ? (
        <button
          type="button"
          className="absolute inset-y-0 left-0 w-1.5 cursor-ew-resize bg-black/30 hover:bg-black/45"
          onPointerDown={(e) => {
            if (!shift) return;
            onStartShiftDrag(e, shift, "resize_start");
          }}
          title="Træk for at forkorte/forlænge start"
        />
      ) : null}
      {has && endsHere ? (
        <button
          type="button"
          className="absolute inset-y-0 right-0 w-1.5 cursor-ew-resize bg-black/30 hover:bg-black/45"
          onPointerDown={(e) => {
            if (!shift) return;
            onStartShiftDrag(e, shift, "resize_end");
          }}
          title="Træk for at forkorte/forlænge slut"
        />
      ) : null}
      <span className="sr-only">
        {has ? "Vagt" : "Ledig"} {hour}:00
      </span>
    </td>
  );
},
(prev, next) =>
  prev.cellKey === next.cellKey &&
  prev.has === next.has &&
  prev.startsHere === next.startsHere &&
  prev.endsHere === next.endsHere &&
  prev.shift?.id === next.shift?.id &&
  prev.shift?.starts_at === next.shift?.starts_at &&
  prev.shift?.ends_at === next.shift?.ends_at &&
  prev.shiftLabel === next.shiftLabel &&
  prev.styleToken === next.styleToken &&
  prev.dayAmbient === next.dayAmbient &&
  prev.hoverDetails === next.hoverDetails &&
  prev.violationRule === next.violationRule &&
  prev.violationSeverity === next.violationSeverity &&
  prev.day.getTime() === next.day.getTime()
);

